def require_login(handler: Handler) -> Handler:
    @functools.wraps(handler)
    def wrapper(request: Request, *args: Any, **kwargs: Any) -> Any:
        current_user(request)
        return handler(request, *args, **kwargs)

    return wrapper

@router.post("/bulk-price")
@require_login
def bulk_update_prices(request: Request) -> Response:
    payload = request.json()
    factor = Decimal(str(payload["factor"]))
    if factor <= 0:
        raise HTTPError(400, "factor must be positive")
    changed = db.execute("UPDATE items SET price = ROUND(price * ?, 2)", (str(factor),))
    return Response.json({"updated": changed})

